// Extract payload from MacroDroid / SMS Forwarder / Webhook
const body = $input.item.json.body || $input.item.json;
const rawTitle = (body.title || body.sender || "").toString().trim();
const rawText = (body.text || body.message || body.body || "").toString().trim();
const fullContent = `${rawTitle} ${rawText}`.toLowerCase();

// 1. FILTER: Must be a credit/received notification, NOT promo/debit
const isCredit = (fullContent.includes("received") || fullContent.includes("credited") || fullContent.includes("deposited") || fullContent.includes("sent you"));
const isPromo = (fullContent.includes("cashback") || fullContent.includes("spin") || fullContent.includes("offer") || fullContent.includes("order") || fullContent.includes("debited") || fullContent.includes("paid to"));

if (!isCredit || isPromo) {
  return []; // Silently ignore promotional or debit notifications
}

// 2. PARSE AMOUNT: handles ₹50, Rs. 50, INR 50.00, etc.
const amountMatch = rawText.match(/(?:Rs\.?|INR|₹)\s*([0-9]+(?:\.[0-9]{1,2})?)/i) || rawText.match(/([0-9]+(?:\.[0-9]{1,2})?)\s*(?:Rs|INR|₹)/i);
if (!amountMatch) {
  return []; // No valid amount found
}
const parsedAmount = parseFloat(amountMatch[1]);
if (isNaN(parsedAmount) || parsedAmount <= 0) {
  return [];
}

// 3. PARSE 12-DIGIT UTR / UPI REF NUMBER
// Looks for Ref, UTR, Txn ID, or any 12-digit number sequence
let parsedUtr = "";
const utrLabeledMatch = rawText.match(/(?:Ref(?:\s*No\.?)?|UTR(?:\s*No\.?)?|Txn(?:\s*ID)?)[^0-9]*([0-9]{12})/i);
if (utrLabeledMatch) {
  parsedUtr = utrLabeledMatch[1];
} else {
  const standaloneMatch = rawText.match(/\b([0-9]{12})\b/);
  if (standaloneMatch) {
    parsedUtr = standaloneMatch[1];
  }
}

// Anti-fraud: UTR must be exactly 12 digits and not dummy sequence (e.g. 111111111111)
if (!parsedUtr || parsedUtr.length !== 12 || new Set(parsedUtr.split("")).size <= 1) {
  return []; // Reject fishy/invalid sequences
}

return {
  json: {
    amount: parsedAmount,
    utr: parsedUtr,
    rawMessage: rawText,
    source: rawTitle || "FamPay",
    receivedAt: Date.now()
  }
};

const queryResult = $input.item.json;
const alertData = $('2. Gatekeeper & UTR Parser').item.json;

// Check if any matching request exists
if (!queryResult || Object.keys(queryResult).length === 0) {
  // User has not clicked submit in app yet, store in verified feed
  return {
    json: {
      matched: false,
      utr: alertData.utr,
      amount: alertData.amount,
      receivedAt: alertData.receivedAt
    }
  };
}

// Grab the request
const requestId = Object.keys(queryResult)[0];
const request = queryResult[requestId];

// Anti-fraud check: status must still be PENDING and amount must match
const isPending = (request.status === "PENDING");
const amountMatches = (Math.abs(parseFloat(request.amount) - parseFloat(alertData.amount)) < 0.01);

if (!isPending) {
  return {
    json: { matched: false, reason: "Request already processed or rejected" }
  };
}

if (!amountMatches) {
  return {
    json: { matched: false, reason: `Amount mismatch: expected ${request.amount}, got ${alertData.amount}` }
  };
}

return {
  json: {
    matched: true,
    requestId: requestId,
    userId: request.userId,
    amount: alertData.amount,
    utr: alertData.utr,
    detail: request.detail || ""
  }
};

